// src/features/demo/index.ts
// Animation showcase screens (app/(app)/demo/*). Mock data only — safe to
// show to anyone, and a copy-paste source for real screens later.

import type { Href } from 'expo-router';

export * from './mockData';
export * from './components/motion';

/**
 * Href for a demo route. Typed routes (.expo/types/router.d.ts) are only
 * regenerated by `expo start`, so new demo paths go through one cast here
 * instead of failing `npm run typecheck` until the dev server has run.
 */
export function demoHref(path: '' | 'vendors' | 'home' | `deal/${string}`): Href {
  return `/(app)/demo${path ? `/${path}` : ''}` as Href;
}
